#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. Five approved setup stages.

run_wizard() {
  local repo_root runtime host_directory
  repo_root="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd)"
  ENV_FILE="${WORK_ITEM_SETUP_ENV:-$repo_root/.work-item-setup.env}"
  [[ ! -L "$ENV_FILE" ]] || { warn "Refusing a symlink settings file: $ENV_FILE"; return 1; }
  TOTAL_STAGES=5
  banner "Work Item delivery setup"

  stage "Choose the agent host and local installation"
  say "Use Linux or WSL Bash, with Git, Python 3 and Node 22+ on PATH."
  say "Settings stay in $ENV_FILE. Never enter tokens or passwords here."
  ask AGENT_HOST "Agent host (codex, claude, cursor):"
  case "$AGENT_HOST" in
    codex) host_directory="$HOME/.codex/skills" ;;
    claude) host_directory="$HOME/.claude/skills" ;;
    cursor) host_directory="$HOME/.cursor/skills" ;;
    *) warn "Choose codex, claude or cursor."; return 1 ;;
  esac
  write_env AGENT_HOST "$AGENT_HOST"
  step "Use the skill root of the actual host. Native Windows hosts need their Windows profile's skill directory translated to a Linux path with wslpath; the Linux-home default is for Linux/WSL agents. See references/windows.md."
  if ! _existing AGENT_SKILLS_DIR >/dev/null; then write_env AGENT_SKILLS_DIR "$host_directory"; fi
  ask AGENT_SKILLS_DIR "Absolute skill-install directory:"
  [[ "$AGENT_SKILLS_DIR" == /* ]] || { warn "Use an absolute Linux/WSL path."; return 1; }
  write_env AGENT_SKILLS_DIR "$AGENT_SKILLS_DIR"
  if ! _existing WORK_ITEM_BIN_DIR >/dev/null; then write_env WORK_ITEM_BIN_DIR "$HOME/.local/bin"; fi
  ask WORK_ITEM_BIN_DIR "Absolute launcher directory:"
  [[ "$WORK_ITEM_BIN_DIR" == /* ]] || { warn "Use an absolute Linux/WSL path."; return 1; }
  write_env WORK_ITEM_BIN_DIR "$WORK_ITEM_BIN_DIR"
  confirm "Use these directories? Existing conflicting installations will be preserved and refused." || return 1

  stage "Enable prerequisite skills and native trust"
  open_url "https://github.com/michael-denyer/pstack-claude#codex"
  open_url "https://github.com/mattpocock/skills#installation-30-second-setup"
  step "Read the section for your chosen host. Have the agent run supported installer commands; handle any native plugin/trust prompts yourself."
  step "For Cursor, use the upstream instructions for that runtime or shared skills; do not run Codex commands."
  step "Confirm the host can actually load poteto-mode, architect, arena, interrogate, swarm, to-spec and wizard. Cache files alone are not discovery proof."
  note "The exact prerequisite list and known source versions are in skills/work-item-delivery/references/prerequisites.md."
  note "Some Codex CLIs do not support plugin commands. Follow the host's current supported installation path; do not guess dashboard controls."
  confirm "Have both prerequisite skillsets loaded in the selected host?" || return 1

  stage "Connect work and specification sources"
  open_url "https://dev.azure.com/"
  step "Open a Work Item you can access. Copy the organization and project segments from its URL."
  ask ADO_ORGANIZATION "Azure DevOps organization name (not a token):"
  [[ "$ADO_ORGANIZATION" =~ ^[A-Za-z0-9._-]+$ ]] || { warn "Enter the organization name from the URL."; return 1; }
  ask ADO_PROJECT "Azure DevOps project name:"
  [[ -n "$ADO_PROJECT" ]] || { warn "Project name is required."; return 1; }
  write_env ADO_ORGANIZATION "$ADO_ORGANIZATION"
  write_env ADO_PROJECT "$ADO_PROJECT"
  step "Connect Azure DevOps through the host's configured connector/MCP and complete SSO there. Ask the agent for a read-only Work Item check."
  step "Follow actual specification links. Connect the relevant Confluence/vault source and browser tool in the same host, or record the access gap."
  ask CONFLUENCE_SITE "Confluence site URL (optional, Enter for none):"
  ask KNOWLEDGE_VAULT "Knowledge-vault path (optional, Enter for none):"
  write_env CONFLUENCE_SITE "$CONFLUENCE_SITE"
  write_env KNOWLEDGE_VAULT "$KNOWLEDGE_VAULT"
  note "Credentials stay with the connector. No CI secret or credential is stored by this script. Missing required access holds affected work."
  confirm "Have you completed the host sign-ins or recorded the remaining access gaps?" || return 1

  stage "Choose models and automatic routing"
  open_url "https://github.com/michael-denyer/pstack-claude/blob/main/plugins/pstack/skills/setup-pstack/SKILL.md"
  step "In the selected agent, request pstack:setup-pstack. Choose model names your current account actually offers and reasoning effort per role."
  step "Configure architect runners, arena cross-judge pool, interrogate reviewers and swarm workers. The example sheet in this package is illustrative, not availability proof."
  ask SESSION_ROUTING "Automatic poteto routing (on or off):"
  [[ "$SESSION_ROUTING" == on || "$SESSION_ROUTING" == off ]] || { warn "Enter on or off."; return 1; }
  write_env SESSION_ROUTING "$SESSION_ROUTING"
  step "Apply that routing choice through setup-pstack. For the native Codex plugin, review/trust its hook through /hooks when enabling it."
  note "Skills-only installations do not install automatic hooks. The host owns its model sheet; this script does not rewrite it."
  confirm "Are the host's available models, effort and routing choices saved?" || return 1

  stage "Install, check and reload"
  python3 "$repo_root/scripts/install-work-item-delivery.py" --skills-dir "$AGENT_SKILLS_DIR" --bin-dir "$WORK_ITEM_BIN_DIR" --settings "$ENV_FILE"
  runtime="$AGENT_SKILLS_DIR/work-item-delivery/vendor/work-item-runtime"
  write_env WORK_ITEM_DELIVERY_ROOT "$runtime"
  python3 "$repo_root/scripts/validate_skills.py"
  node "$runtime/bin/wid.mjs" help
  node --test "$runtime"/test/*.test.mjs
  PYTHONDONTWRITEBYTECODE=1 python3 -m unittest discover -s "$runtime/test" -p test_draft_spec.py
  step "Reload/start a new host session. Request work-item-delivery and proof-of-work, and confirm the installed package is the one the host loads."
  step "Ask for investigation and a developer plan for a real Work Item. Setup never approves that plan or starts product implementation."
  note "Add $WORK_ITEM_BIN_DIR to your shell PATH if needed, or invoke the printed launcher directly."
  confirm "Does the new session load the intended workflow skills?" || return 1
  SKIPPED+=("Live connectors, model execution, hook routing and actual Work Item readiness are not certified by offline tests.")
  finish
}

run_wizard "$@"; exit
